18	/**
19	 * CloudflareServices - "Packed" Workers AI & Substrate Layer
20	 * Supports automated account detection and free-tier optimization.
21	 */
22	export class CloudflareServices {
23	    private accountId: string | undefined;
24	    private readonly apiToken: string | undefined;
25	    private authEmail: string | undefined;
26	    private readonly baseUrl: string = 'https://api.cloudflare.com/client/v4/accounts';
27	
28	    private readonly config: CloudflareConfig;
29	    private readonly hexagramManager: HexagramManager | undefined;
30	
31	    constructor(config: CloudflareConfig) {
32	        this.config = config;
33	        this.accountId = (config.accountId || process.env['CLOUDFLARE_ACCOUNT_ID'] || '').trim();
34	        this.apiToken = (config.apiToken || process.env['CLOUDFLARE_API_TOKEN'] || process.env['CLOUDFLARE_API_KEY'] || '').trim();
35	        this.authEmail = (config.authEmail || process.env['CLOUDFLARE_AUTH_EMAIL'] || '').trim();
36	        this.hexagramManager = config.hexagramManager;
37	        if (this.authEmail && this.apiToken) {
38	            this.useGlobalKey = true;
39	        }
40	    }
41	
42	    public getAccountId(): string | undefined {
43	        return this.accountId;
44	    }
45	
46	    /**
47	     * Auto-detect Cloudflare account ID from local wrangler context if not provided
48	     * Now returns a ternary status: 1 (Global), 0 (Token), -1 (Unauth)
49	     */
50	    async auditAbilities(): Promise<Result<{ accountId?: string; status: number }>> {
51	        try {
52	            // If missing accountId or email, try to get it from wrangler
53	            if (!this.accountId || !this.authEmail) {
54	                logger.info('Attempting to complete Cloudflare context via wrangler...');
55	                const { stdout: whoami } = await $`wrangler whoami 2>&1`;
56	
57	                const match = whoami.match(/Account ID:\s+([a-f0-9]+)/i);
58	                if (match && match[1]) {
59	                    this.accountId = match[1].trim();
60	                }
61	
62	                const emailMatch = whoami.match(/associated with the email\s+([^\s]+)/i);
63	                if (emailMatch && emailMatch[1]) {
64	                    // Remove trailing dot if present (common in "email@domain.com.")
65	                    this.authEmail = emailMatch[1].trim().replace(/\.$/, '');
66	                }
67	            }
68	
69	            // Verify Token
70	            const verification = await this.verifyToken();
71	            if (!verification.ok) {
72	                const error = (verification as { ok: false; error: Error }).error;
73	                return { ok: false, error: new Error(`Token verification failed: ${error.message}`) };
74	            }
75	
76	            // Determine Ternary Status
77	            const ternaryStatus = this.useGlobalKey ? 1 : 0;
78	
79	            // Pin Auth Hex Card (Line 4: Environment)
80	            if (this.hexagramManager) {
81	                void this.hexagramManager.pinCard(4, 'Cloudflare Auth State',
82	                    this.useGlobalKey ? 'Sovereign Global Key active' : 'Standard API Token active',
83	                    this.useGlobalKey ? YaoState.OldYang : YaoState.YoungYang);
84	            }
85	
86	            const result: { accountId?: string; status: number } = { status: ternaryStatus };
87	            if (this.accountId) {
88	                result.accountId = this.accountId;
89	            }
90	            return { ok: true, value: result };
91	        } catch (error) {
92	            logger.error({ error }, 'Cloudflare ability audit failed');
93	            return { ok: false, error: error as Error };
94	        }
95	    }
96	
97	    async verifyToken(): Promise<Result<void>> {
98	        if (!this.apiToken) return { ok: false, error: new Error('No API Token provided') };
99	
100	        try {
101	            // 1. Attempt Bearer Token against Core API
102	            const response = await fetch('https://api.cloudflare.com/client/v4/user/tokens/verify', {
103	                method: 'GET',
104	                headers: {
105	                    'Authorization': `Bearer ${this.apiToken}`,
106	                    'Content-Type': 'application/json'
107	                }
108	            });
109	
110	            let bearerError = 'Bearer Auth Failed';
111	
112	            if (response.ok) {
113	                const data = await response.json() as any;
114	                if (data.success && data.result.status === 'active') {
115	                    return { ok: true, value: undefined };
116	                }
117	                bearerError = data.errors?.[0]?.message || 'Invalid Token Status';
118	            } else {
119	                bearerError = `HTTP ${response.status}`;
120	            }
121	
122	            // 2. Fallback: Global Key
123	            if (this.authEmail) {
124	                const globalResponse = await fetch('https://api.cloudflare.com/client/v4/user', {
125	                    method: 'GET',
126	                    headers: {
127	                        'X-Auth-Email': this.authEmail,
128	                        'X-Auth-Key': this.apiToken,
129	                        'Content-Type': 'application/json'
130	                    }
131	                });
132	
133	                if (globalResponse.ok) {
134	                    const gData = await globalResponse.json() as any;
135	                    if (gData.success) {
136	                        this.useGlobalKey = true;
137	                        return { ok: true, value: undefined };
138	                    }
139	                }
140	            }
141	
142	            // 3. Gateway Token Bypass
143	            // If we have a Gateway URL, the token might be a Gateway-Scoped token (not a Global User token).
144	            // In this case, standard verification fails, but the Gateway request might succeed.
145	            if (this.config.gatewayUrl) {
146	                logger.warn('Standard auth failed, but Gateway URL is present. Assuming Gateway-Scoped Token and proceeding.');
147	                return { ok: true, value: undefined };
148	            }
149	
150	            return { ok: false, error: new Error(`Authentication failed. Bearer error: "${bearerError}". Global Key fallback also failed.`) };
151	        } catch (e) {
152	            return { ok: false, error: e as Error };
153	        }
154	    }
155	
156	    private useGlobalKey: boolean = false;
157	
158	    private getHeaders(contentType: string = 'application/json'): Record<string, string> {
159	        if (this.useGlobalKey && this.authEmail && this.apiToken) {
160	            return {
161	                'X-Auth-Email': this.authEmail,
162	                'X-Auth-Key': this.apiToken,
163	                'Content-Type': contentType
164	            };
165	        }
166	        return {
167	            'Authorization': `Bearer ${this.apiToken}`,
168	            'Content-Type': contentType
169	        };
170	    }
171	
172	    /**
173	     * Run a Workers AI model with ternary prioritization logic
174	     */
175	    async runAi<T = any>(model: string, input: any): Promise<Result<T>> {
176	        // Ternary Decision Pathing
